"""Turn NimBLE's syscfg.yml files into Kconfig fragments and a syscfg.h.

NimBLE configures itself through ``syscfg.yml`` files that Apache newt
compiles into a per-target ``syscfg.h``. That forces a newt checkout and one
checked-in header per SoC. This script replaces both: every ``syscfg.defs``
entry becomes a Kconfig symbol (``CONFIG_NIMBLE_<NAME>``), and the generated
``syscfg.h`` defines ``MYNEWT_VAL_<NAME>`` from it. Per-SoC values then live in
``soc/<soc>/Kconfig.defconfig`` like every other PebbleOS setting.

Run it after bumping the NimBLE submodule::

    python3 third_party/nimble/scripts/gen_syscfg.py

``--check`` reports whether the checked-in output is stale without writing.
See ``README.md`` for the mapping rules and their limits.
"""

import argparse
import collections
import os
import pathlib
import re
import sys
import textwrap

import yaml

SCRIPTS_DIR = os.path.dirname(os.path.abspath(__file__))
NIMBLE_DIR = os.path.dirname(SCRIPTS_DIR)

SPDX = (
    "# SPDX-FileCopyrightText: 2026 Core Devices LLC\n"
    "# SPDX-License-Identifier: Apache-2.0\n"
)
BANNER = "# Generated by scripts/gen_syscfg.py -- do not edit.\n"

# syscfg options become CONFIG_NIMBLE_<name>, keeping them apart from the
# PebbleOS symbols (several of which are also called BLE_*).
PREFIX = "NIMBLE_"


def die(msg):
    sys.exit(f"gen_syscfg: {msg}")


# -- YAML ---------------------------------------------------------------------


class Loader(yaml.SafeLoader):
    """SafeLoader that leaves ``NULL``, ``yes`` and friends as strings.

    syscfg values are C tokens: ``value: NULL`` means the C ``NULL``, while an
    empty ``value:`` means "leave the option undefined". YAML 1.1 collapses
    both to None, so the null and bool resolvers have to go.
    """


Loader.yaml_implicit_resolvers = {
    ch: [
        (tag, regexp)
        for tag, regexp in resolvers
        if tag.rsplit(":", 1)[-1] not in ("null", "bool")
    ]
    for ch, resolvers in yaml.SafeLoader.yaml_implicit_resolvers.items()
}


def load_yaml(path):
    with open(path) as f:
        return yaml.load(f, Loader=Loader) or {}


# -- syscfg expressions -------------------------------------------------------

TOKEN_RE = re.compile(
    r"""\s+
      | MYNEWT_VAL\s*\(\s*(?P<call>[A-Za-z_][A-Za-z0-9_]*)\s*\)
      | (?P<op><=|>=|==|!=|&&|\|\||[<>!()])
      | (?P<string>"[^"]*")
      | (?P<number>0[xX][0-9a-fA-F]+|\d+)
      | (?P<name>[A-Za-z_][A-Za-z0-9_]*)
    """,
    re.VERBOSE,
)

COMPARISONS = ("<", ">", "<=", ">=", "==", "!=")


class ExprError(Exception):
    """The expression has no Kconfig equivalent."""


def tokenize(text):
    tokens = []
    pos = 0
    while pos < len(text):
        match = TOKEN_RE.match(text, pos)
        if not match:
            raise ExprError(f"cannot tokenize {text!r} at offset {pos}")
        pos = match.end()
        if match.group("call"):
            tokens.append(("name", match.group("call")))
        elif match.group("op"):
            tokens.append(("op", match.group("op")))
        elif match.group("string"):
            tokens.append(("string", match.group("string")[1:-1]))
        elif match.group("number"):
            tokens.append(("number", match.group("number")))
        elif match.group("name"):
            name = match.group("name")
            name = name.removeprefix("MYNEWT_VAL_")
            tokens.append(("name", name))
    return tokens


class Parser:
    """Recursive-descent parser for the C expressions syscfg allows."""

    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0

    def peek(self):
        return self.tokens[self.pos] if self.pos < len(self.tokens) else (None, None)

    def eat(self, kind, value):
        if self.peek() == (kind, value):
            self.pos += 1
            return True
        return False

    def parse(self):
        node = self.parse_or()
        if self.pos != len(self.tokens):
            raise ExprError("trailing tokens")
        return node

    def parse_or(self):
        node = self.parse_and()
        while self.eat("op", "||"):
            node = ("or", node, self.parse_and())
        return node

    def parse_and(self):
        node = self.parse_unary()
        while self.eat("op", "&&"):
            node = ("and", node, self.parse_unary())
        return node

    def parse_unary(self):
        if self.eat("op", "!"):
            return ("not", self.parse_unary())
        return self.parse_comparison()

    def parse_comparison(self):
        left = self.parse_atom()
        kind, value = self.peek()
        if kind == "op" and value in COMPARISONS:
            self.pos += 1
            return ("cmp", value, left, self.parse_atom())
        return left

    def parse_atom(self):
        if self.eat("op", "("):
            node = self.parse_or()
            if not self.eat("op", ")"):
                raise ExprError("unbalanced parenthesis")
            return node
        kind, value = self.peek()
        if kind in ("name", "number", "string"):
            self.pos += 1
            return (kind, value)
        raise ExprError(f"unexpected token {value!r}")


def parse_expr(text):
    return Parser(tokenize(str(text).strip())).parse()


def unquote(text):
    """Strip the quotes syscfg puts around a condition used as a YAML key."""
    text = text.strip()
    if len(text) > 1 and text[0] == text[-1] and text[0] in "\"'":
        return text[1:-1]
    return text


class Renderer:
    """Renders parsed syscfg expressions as Kconfig expressions."""

    def __init__(self, model):
        self.model = model

    def entry(self, name):
        entry = self.model.defs.get(name)
        if entry is None:
            raise ExprError(f"unknown option {name}")
        if entry.kconfig not in ("bool", "int", "hex", "string"):
            raise ExprError(f"{name} has no scalar Kconfig symbol")
        return entry

    def truth(self, name):
        """The option as a Kconfig condition."""
        entry = self.entry(name)
        return entry.sym if entry.kconfig == "bool" else f"{entry.sym} != 0"

    def symbol(self, name):
        """The option as a Kconfig number. A bool is not one."""
        entry = self.entry(name)
        if entry.kconfig == "bool":
            raise ExprError(f"{name} is a bool")
        return entry.sym

    def choice_member(self, name, value):
        entry = self.model.defs.get(name)
        if entry is None or value not in entry.members:
            raise ExprError(f"{name} has no choice {value!r}")
        return f"{entry.sym}_{value.upper()}"

    def condition(self, node):
        kind = node[0]
        if kind == "or":
            return f"({self.condition(node[1])} || {self.condition(node[2])})"
        if kind == "and":
            return f"({self.condition(node[1])} && {self.condition(node[2])})"
        if kind == "not":
            return f"!{self.condition(node[1])}"
        if kind == "cmp":
            _, op, left, right = node
            if left[0] == "name" and right[0] == "string":
                member = self.choice_member(left[1], right[1])
                if op not in ("==", "!="):
                    raise ExprError(f"cannot {op} a choice")
                return member if op == "==" else f"!{member}"
            return f"{self.value(left)} {op} {self.value(right)}"
        if kind == "name":
            return self.truth(node[1])
        raise ExprError(f"cannot use {kind} as a condition")

    def value(self, node):
        kind = node[0]
        if kind == "name":
            return self.symbol(node[1])
        if kind == "number":
            return node[1]
        if kind == "string":
            return f'"{node[1]}"'
        raise ExprError(f"cannot use {kind} as a value")


# -- values -------------------------------------------------------------------

INT_RE = re.compile(r"[+-]?\d+")
HEX_RE = re.compile(r"[+-]?0[xX][0-9a-fA-F]+")


def classify(value):
    """Classify a syscfg value as ``(kind, text)``.

    ``int``, ``hex`` and ``string`` map straight onto a Kconfig type. ``expr``
    is a C expression, which only reaches Kconfig when it is a reference to
    another option or a boolean formula over them. ``undef`` means the option
    is deliberately left undefined.
    """
    if isinstance(value, int):
        return "int", str(value)
    text = "" if value is None else str(value).strip()
    if not text:
        return "undef", ""
    if HEX_RE.fullmatch(text):
        return "hex", text
    if INT_RE.fullmatch(text):
        return "int", text
    if text.startswith('"') and text.endswith('"'):
        return "string", text
    return "expr", text


