# Boilerplate NimBLE opens a description with, which says nothing a prompt
# needs.
PREAMBLE_RE = re.compile(
    r"^(?:this\s+)?(?:option|setting|value|macro)?\s*"
    r"(?:is\s+used\s+to\s+)?"
    r"(?:enables?(?:/disables?)?|enabled|disables?|defines?|specifies?|sets?"
    r"|indicates?|configures?|determines?|selects?|controls?|provides?|adds?"
    r"|allows?\s+to|causes?|is|if\s+enabled,?)\s+"
    r"(?:support\s+for\s+)?(?:the\s+|a\s+|an\s+)?",
    re.IGNORECASE,
)
# Where a too-long opening sentence can be cut and still read as a label.
CLAUSE_RE = re.compile(
    r",\s|\s(?:that|which|when|so|but|unless|because|and)\s|\sfor\s+controlling\s"
)
TRAILING_RE = re.compile(
    r"\s*\((?:0/1)\)\s*$|\s+feature$|[,.:]\s*i\.e\.?$|[.:,]$", re.IGNORECASE
)
SENTENCE_RE = re.compile(r"(?<=[a-z0-9\)])\.\s")
PROMPT_LIMIT = 66


def prompt_from_name(name):
    """A last-resort prompt, spelled out from the option's own name."""
    words = []
    for word in name.split("_"):
        if word in ACRONYMS:
            words.append(word)
        else:
            words.append(SPELLED.get(word, word.lower()))
    text = " ".join(words)
    return text[0].upper() + text[1:]


ARTICLE_RE = re.compile(r"^(?:the|a|an)\s+", re.IGNORECASE)


def tidy(text):
    text = TRAILING_RE.sub("", text.strip()).strip()
    text = PREAMBLE_RE.sub("", text, count=1).strip()
    text = ARTICLE_RE.sub("", text).strip()
    return TRAILING_RE.sub("", text).strip()


def prompt(entry):
    """A readable prompt: NimBLE's own words where they fit, else the name.

    The description's opening sentence is what a person would write on the
    line anyway, minus the boilerplate it tends to start with. Where it is too
    long or missing, the option's name spelled out reads better than a
    truncated sentence.
    """
    text = " ".join((entry.description or "").split())
    if text:
        first = tidy(SENTENCE_RE.split(text)[0])
        if len(first) > PROMPT_LIMIT:
            head = CLAUSE_RE.split(first)[0].strip()
            if len(head.split()) >= 3:
                first = tidy(head)
        if 0 < len(first) <= PROMPT_LIMIT:
            return (first[0].upper() + first[1:]).replace('"', "'")
    return prompt_from_name(entry.name)


# -- syscfg model -------------------------------------------------------------


class Def:
    """One ``syscfg.defs`` entry."""

    def __init__(self, name, body, area, condition, section):
        if not isinstance(body, dict):
            body = {"value": body}
        self.name = name
        self.area = area
        # Condition of the enclosing `syscfg.defs.<cond>:` block, if any.
        self.condition = condition
        self.section = section
        self.value = body.get("value")
        self.description = body.get("description") or ""
        self.members = list(body.get("choices") or [])
        # Choice members that map onto a C expression rather than onto
        # MYNEWT_VAL_<name>__<member>; only set through an override.
        self.enum = None
        self.range = body.get("range")
        self.restrictions = body.get("restrictions") or []
        if isinstance(self.restrictions, str):
            self.restrictions = [self.restrictions]
        self.experimental = (
            bool(body.get("experimental")) or body.get("state") == "experimental"
        )
        # Defaults contributed by `syscfg.vals` blocks, most specific first.
        self.overrides = []
        self.kconfig = None
        self.kind = None
        self.default = None

    @property
    def sym(self):
        return PREFIX + self.name

    @property
    def optional(self):
        """Whether the option can be missing from autoconf.h.

        A conditional def, or one in an area that is not always built, behaves
        like a newt package that is not part of the target: the option is
        simply not defined.
        """
        return bool(self.condition) or bool(self.area.depends)


def scan_sections(text):
    """Map option name -> section title, from the file's banner comments.

    NimBLE groups its defs with comments such as ``# L2CAP settings.``; those
    are the only grouping upstream offers, and they make good Kconfig menus.
    """
    sections = {}
    banner = None
    current = None
    in_defs = False
    for line in text.splitlines():
        if re.match(r"^syscfg\.defs(\.|:)", line):
            in_defs, current, banner = True, None, None
            continue
        if line and not line[0].isspace():
            in_defs = False
            continue
        if not in_defs:
            continue
        comment = re.match(r"^ {4}#+ ?(.*)$", line)
        if comment:
            if banner is None:
                banner = comment.group(1).strip()
            continue
        key = re.match(r"^ {4}([A-Za-z_][A-Za-z0-9_]*):", line)
        if key:
            if banner is not None:
                title = re.fullmatch(
                    r"(.+?)\s+(settings|options)\.?", banner, re.IGNORECASE
                )
                current = title.group(1) if title else None
            sections[key.group(1)] = current
            banner = None
        elif line.strip():
            banner = None
    return sections


def parse_package(path, area, nimble_root):
    """Parse one syscfg.yml, following ``$import``. Returns ``(defs, vals)``."""
    data = load_yaml(path)
    with open(path) as f:
        sections = scan_sections(f.read())

    defs, vals = [], []
    for key, body in data.items():
        if key == "syscfg.defs" or key.startswith("syscfg.defs."):
            condition = unquote(key[len("syscfg.defs.") :]) or None
            for name, entry in (body or {}).items():
                defs.append(Def(name, entry, area, condition, sections.get(name)))
        elif key == "syscfg.vals" or key.startswith("syscfg.vals."):
            vals.append((unquote(key[len("syscfg.vals.") :]) or None, body or {}))
        elif key == "$import":
            for ref in body or []:
                sub_defs, sub_vals = parse_package(
                    os.path.join(
                        nimble_root, ref.replace("@apache-mynewt-nimble/", "")
                    ),
                    area,
                    nimble_root,
                )
                defs += sub_defs
                vals += sub_vals
        # syscfg.logs and syscfg.restrictions describe newt's log registry and
        # cross-package assertions; neither has a Kconfig equivalent.
    return defs, vals


class Area:
    """A group of packages rendered into one Kconfig.<id> file."""

    def __init__(self, spec):
        self.id = spec["id"]
        self.title = spec["title"]
        self.packages = spec.get("packages") or []
        self.files = spec.get("files") or []
        # A raw Kconfig expression: when it is false the packages are not part
        # of the build, so none of their options is defined.
        self.depends = spec.get("depends")
        self.defs = []

    @property
    def path(self):
        return os.path.join(NIMBLE_DIR, f"Kconfig.{self.id}")


class Model:
    def __init__(self, config):
        self.areas = [Area(spec) for spec in config["areas"]]
        self.overrides = config.get("overrides") or {}
        self.booleans = set(
            load_yaml(os.path.join(SCRIPTS_DIR, config["booleans"]))["booleans"]
        )
        self.defs = {}
        # Surprises worth acting on, versus the options Kconfig cannot express
        # and the values aimed at packages PebbleOS does not build. The latter
        # are expected on every run, so they only appear under --verbose.
        self.warnings = []
        self.notes = []

    def load(self, nimble_root):
        pending = []
        for area in self.areas:
            paths = [os.path.join(nimble_root, p, "syscfg.yml") for p in area.packages]
            paths += [os.path.join(SCRIPTS_DIR, f) for f in area.files]
            for path in paths:
                if not os.path.exists(path):
                    die(f"missing syscfg file: {path}")
                defs, vals = parse_package(path, area, nimble_root)
                for entry in defs:
                    if entry.name in self.defs:
                        die(f"{entry.name} defined twice ({path})")
                    self.defs[entry.name] = entry
                    area.defs.append(entry)
                pending += [(area, cond, body) for cond, body in vals]

        self.apply_overrides()

        # syscfg.vals only apply when their own package is built, so they
        # inherit the area's dependency on top of their own condition.
        for area, condition, body in pending:
            for name, value in body.items():
                entry = self.defs.get(name)
                if entry is None:
                    self.notes.append(f"{area.id}: value for unknown option {name}")
                    continue
                entry.overrides.append((area.depends, condition, value))

        self.scan_assignments(nimble_root)
        self.check_booleans()
        self.resolve_types()

    def scan_assignments(self, nimble_root):
        """Collect every value any syscfg.yml in the tree gives an option.

        NimBLE's own apps, targets and test setups are a large corpus of
        intended values. One of them assigning an option something other than
        0 or 1 settles that the option is a number.
        """
        self.assigned = {}
        for path in sorted(pathlib.Path(nimble_root).rglob("syscfg*.yml")):
            try:
                data = load_yaml(path)
            except yaml.YAMLError as e:
                self.notes.append(f"{path}: unreadable ({e})")
                continue
            for key, body in (data or {}).items():
                if not (key == "syscfg.vals" or key.startswith("syscfg.vals.")):
                    continue
                for name, value in (body or {}).items():
                    self.assigned.setdefault(name, set()).add(classify(value))

    def apply_overrides(self):
        for name, spec in self.overrides.items():
            entry = self.defs.get(name)
            if entry is None:
                die(f"override for unknown option {name}")
            if "enum" in spec:
                entry.enum = spec["enum"]
                entry.members = list(spec["enum"])
                entry.value = spec["default"]
            if "value" in spec:
                entry.value = spec["value"]
            if "description" in spec:
                entry.description = spec["description"]

    def check_booleans(self):
        """Reject entries in booleans.yml that NimBLE's own files disprove.

        Nothing here can show that an option *is* a flag -- that is the
        judgement the list records -- but plenty can show that it is not.
        """
        for name in sorted(self.booleans):
            entry = self.defs.get(name)
            if entry is None:
                die(f"booleans.yml lists {name}, which no package defines")
            if entry.range:
                die(f"booleans.yml lists {name}, which has a range ({entry.range})")
            if entry.kind == "int" and entry.default not in ("0", "1"):
                die(f"booleans.yml lists {name}, whose value is {entry.default}")
            for kind, text in sorted(self.assigned.get(name, ())):
                if kind != "int" or text not in ("0", "1"):
                    die(f"booleans.yml lists {name}, which NimBLE sets to {text}")

    def resolve_types(self):
        """Settle every option's Kconfig type.

        An option's type depends on the options its value and condition name,
        and demoting one option can demote another, so the pass repeats until
        nothing changes.
        """
        for entry in self.defs.values():
            entry.kind, entry.default = classify(entry.value)
            if entry.members:
                entry.kconfig = "choice"
            elif entry.kind == "undef":
                entry.kconfig = None
            elif entry.kind in ("hex", "string"):
                entry.kconfig = entry.kind
            elif entry.name in self.booleans:
                entry.kconfig = "bool"
            else:
                entry.kconfig = "int"

        renderer = Renderer(self)
        changed = True
        while changed:
            changed = False
            for entry in self.defs.values():
                if entry.kconfig is None:
                    continue
                try:
                    if entry.condition:
                        renderer.condition(parse_expr(entry.condition))
                    if entry.kind == "expr" and entry.kconfig != "choice":
                        node = parse_expr(entry.default)
                        if node[0] == "name":
                            # An option that just renames another one is
                            # whatever that one is; taking a count as a flag
                            # here would quietly truncate it to 0 or 1.
                            referenced = renderer.entry(node[1]).kconfig
                            if entry.kconfig != referenced:
                                entry.kconfig = referenced
                                changed = True
                        else:
                            renderer.condition(node)
                except ExprError as e:
                    # Arithmetic, a plain C macro, or a value or condition on
                    # an option that has no symbol: NimBLE's own value stays
                    # in the header and the option stays out of Kconfig.
                    self.notes.append(f"{entry.name}: not configurable ({e})")
                    entry.kconfig = None
                    changed = True

    def defaults(self, entry, renderer):
        """Kconfig ``default`` lines for an option, most specific first.

        Every default carries the area's dependency, so an option whose
        package is not built falls back to Kconfig's implicit zero. Without
        that, a hidden option would still hand its NimBLE default to the
        expressions that read it.
        """
        own = entry.area.depends
        lines = []
        for depends, condition, value in entry.overrides:
            conditions = [c for c in (own, depends) if c]
            if condition:
                try:
                    conditions.append(renderer.condition(parse_expr(condition)))
                except ExprError as e:
                    self.notes.append(f"{entry.name}: dropped conditional value ({e})")
                    continue
            try:
                text = literal(entry, value)
            except ExprError as e:
                self.warnings.append(f"{entry.name}: dropped value {value!r} ({e})")
                continue
            lines.append(f"    default {text}" + guard(dict.fromkeys(conditions)))

        if entry.kind == "expr":
            node = parse_expr(entry.default)
            if node[0] == "name" and entry.kconfig == "bool":
                lines.append(f"    default {renderer.truth(node[1])}" + guard([own]))
            elif node[0] == "name":
                lines.append(f"    default {renderer.value(node)}" + guard([own]))
            else:
                conditions = [own] if own else []
                conditions.append(renderer.condition(node))
                on, off = ("y", "n") if entry.kconfig == "bool" else ("1", "0")
                lines.append(f"    default {on}" + guard(conditions))
                lines.append(f"    default {off}" + guard([own]))
        elif entry.kind != "undef":
            lines.append(f"    default {literal(entry, entry.value)}" + guard([own]))

        # Kconfig compares a valueless int as a string, so `SYM != 0` would be
        # true for an option every default of which is conditional. Spell the
        # zero out. A bool needs none of this: unset already means false.
        # An unconditional `default n` says what Kconfig already does.
        if entry.kconfig == "bool":
            return [line for line in lines if line != "    default n"]

        if entry.kconfig in ("int", "hex") and all(" if " in line for line in lines):
            zero = "    default 0x0" if entry.kconfig == "hex" else "    default 0"
            if lines and lines[-1] == f"{zero} if {own}":
                lines[-1] = zero
            else:
                lines.append(zero)
        return lines


# -- Kconfig output -----------------------------------------------------------


def literal(entry, value):
    """Render a syscfg value as a Kconfig default for this option."""
    kind, text = classify(value)
    if entry.kconfig == "bool":
        if kind != "int" or text not in ("0", "1"):
            raise ExprError(f"{text} is not a flag")
        return "y" if text == "1" else "n"
    if kind not in ("int", "hex", "string"):
        raise ExprError(f"{text} is not a literal")
    return text


def guard(conditions):
    """Render an ``if`` guard from the conditions that are not empty."""
    conditions = [c for c in conditions if c]
    return f" if {' && '.join(conditions)}" if conditions else ""


def help_text(entry):
    lines = []
    description = " ".join((entry.description or "").split())
    if description and tidy(description).casefold() != prompt(entry).casefold():
        lines += textwrap.wrap(description, 66)
    if entry.experimental:
        lines += ["", "Experimental upstream."]
    if entry.range and not re.fullmatch(r"\S+\s*\.\.\s*\S+", str(entry.range).strip()):
        lines += ["", f"Valid values: {entry.range}."]
    if entry.restrictions:
        lines += ["", "NimBLE restrictions, which Kconfig does not enforce:"]
        lines += [f"  - {restriction}" for restriction in entry.restrictions]
    while lines and not lines[0]:
        lines.pop(0)
    if not lines:
        return []
    return ["    help"] + [f"      {line}".rstrip() for line in lines]


def render_range(entry, renderer):
    if not entry.range:
        return []
    # Kconfig only knows intervals; an enumerated range goes to the help text.
    interval = re.fullmatch(r"(\S+)\s*\.\.\s*(\S+)", str(entry.range).strip())
    if not interval:
        return []
    try:
        low, high = (renderer.value(parse_expr(end)) for end in interval.groups())
    except ExprError:
        return []
    # Guarded like the defaults, so the zero an unbuilt package takes is not
    # clamped into the range.
    return [f"    range {low} {high}" + guard([entry.area.depends])]


def render_choice(entry, renderer):
    # Named so a Kconfig.defconfig can reopen it and pick another default.
    out = [f"choice {entry.sym}_CHOICE", f'    prompt "{prompt(entry)}"']
    out.append(f"    default {entry.sym}_{str(entry.value).upper()}")
    if entry.condition:
        out.append(f"    depends on {renderer.condition(parse_expr(entry.condition))}")
    out += help_text(entry)
    for member in entry.members:
        out += ["", f"config {entry.sym}_{member.upper()}", f'    bool "{member}"']
    return out + ["", "endchoice"]


def render_option(entry, renderer, model):
    if entry.kconfig is None:
        if fallback(entry) is None:
            return [f"# {entry.name} is left undefined by syscfg.h."]
        return [f"# {entry.name} is fixed by syscfg.h ({entry.value})."]
    if entry.kconfig == "choice":
        return render_choice(entry, renderer)

    out = [f"config {entry.sym}", f'    {entry.kconfig} "{prompt(entry)}"']
    if entry.condition:
        out.append(f"    depends on {renderer.condition(parse_expr(entry.condition))}")
    out += render_range(entry, renderer)
    out += model.defaults(entry, renderer)
    return out + help_text(entry)


def render_area(area, model, renderer):
    out = [SPDX, BANNER, "\n"]
    out.append(f'menu "{area.title}"\n')
    if area.depends:
        # `visible if` rather than `if`: a plain `if` would also gate every
        # `default` below, leaving the options valueless rather than zero for
        # the builds that leave their package out.
        out.append(f"visible if {area.depends}\n")

    section = None
    for entry in area.defs:
        if entry.section != section:
            if section:
                out.append("\nendmenu\n")
            section = entry.section
            if section:
                out.append(f'\nmenu "{section}"\n')
        out.append("\n" + "\n".join(render_option(entry, renderer, model)) + "\n")
    if section:
        out.append("\nendmenu\n")

    out.append("\nendmenu\n")
    return "".join(out)


# -- syscfg.h output ----------------------------------------------------------


def fallback(entry):
    """The value an option takes when its Kconfig symbol is not set.

    ``None`` means "leave it undefined", which is what NimBLE sees for an
    option whose package is not part of the build. A bool has no fallback:
    absent from autoconf.h is exactly what false looks like.
    """
    if entry.kind == "undef" or entry.optional:
        return None
    if entry.kind == "string":
        return entry.default
    return f"({entry.default})"


def render_header_option(entry):
    name = f"MYNEWT_VAL_{entry.name}"
    out = [f"/* {entry.name} */"]

    if entry.kconfig == "choice" and entry.enum:
        # One value picked from a fixed set of C expressions; the Kconfig
        # choice always selects exactly one, so there is nothing to fall back
        # on.
        for member, value in entry.enum.items():
            out.append(f"#ifdef CONFIG_{entry.sym}_{member.upper()}")
            out.append(f"#define {name} ({value})")
            out.append("#endif")
        return out

    if entry.kconfig == "choice":
        # Like newt, the option itself is defined only where the package that
        # declares it is part of the build.
        selected = " || ".join(
            f"defined(CONFIG_{entry.sym}_{member.upper()})" for member in entry.members
        )
        out.append(f"#if {selected}")
        out.append(f"#define {name} (1)")
        out.append("#endif")
        for member in entry.members:
            out.append(f"#ifdef CONFIG_{entry.sym}_{member.upper()}")
            out.append(f"#define {name}__{member} (1)")
            out.append("#else")
            out.append(f"#define {name}__{member} (0)")
            out.append("#endif")
        return out

    if entry.kconfig == "bool":
        out.append(f"#ifdef CONFIG_{entry.sym}")
        out.append(f"#define {name} (1)")
        out.append("#else")
        out.append(f"#define {name} (0)")
        out.append("#endif")
        return out

    default = fallback(entry)
    if entry.kconfig is None:
        if default is None:
            return out + [f"#undef {name}"]
        return out + [f"#define {name} {default}"]

    body = f"CONFIG_{entry.sym}" if entry.kind == "string" else f"(CONFIG_{entry.sym})"
    out.append(f"#ifdef CONFIG_{entry.sym}")
    out.append(f"#define {name} {body}")
    out.append("#else")
    out.append(f"#undef {name}" if default is None else f"#define {name} {default}")
    out.append("#endif")
    return out


def render_header(model):
    out = [
        "/*\n",
        " * SPDX-FileCopyrightText: 2026 Core Devices LLC\n",
        " * SPDX-License-Identifier: Apache-2.0\n",
        " *\n",
        " * Generated by scripts/gen_syscfg.py -- do not edit.\n",
        " *\n",
        " * Maps NimBLE's syscfg options onto the Kconfig symbols generated\n",
        " * alongside this header. An option whose symbol is not set falls back\n",
        " * on NimBLE's own default, or stays undefined when it belongs to a\n",
        " * part of the stack this build does not include.\n",
        " */\n",
        "\n",
        "#ifndef H_MYNEWT_SYSCFG_\n",
        "#define H_MYNEWT_SYSCFG_\n",
        "\n",
        "#define MYNEWT_VAL(_name) MYNEWT_VAL_##_name\n",
        "#define MYNEWT_VAL_CHOICE(_name, _val) MYNEWT_VAL_##_name##__##_val\n",
    ]
    for area in model.areas:
        out.append(f"\n/*** {area.title} */\n")
        for entry in area.defs:
            out.append("\n" + "\n".join(render_header_option(entry)) + "\n")
    out.append("\n#endif /* H_MYNEWT_SYSCFG_ */\n")
    return "".join(out)


# -- driver -------------------------------------------------------------------


def write(path, content, check):
    current = None
    if os.path.exists(path):
        with open(path) as f:
            current = f.read()
    if current == content:
        return False
    if check:
        print(f"stale: {os.path.relpath(path, NIMBLE_DIR)}")
        return True
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, "w") as f:
        f.write(content)
    print(f"wrote: {os.path.relpath(path, NIMBLE_DIR)}")
    return True


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument(
        "--check", action="store_true", help="fail if the output is stale"
    )
    parser.add_argument(
        "--verbose",
        action="store_true",
        help="also list the options that stay out of Kconfig",
    )
    parser.add_argument(
        "--config",
        default=os.path.join(SCRIPTS_DIR, "config.yml"),
        help="areas, port options and overrides",
    )
    args = parser.parse_args()

    config = load_yaml(args.config)
    nimble_root = os.path.join(NIMBLE_DIR, config.get("nimble", "mynewt-nimble"))
    if not os.path.isdir(nimble_root):
        die(f"NimBLE checkout not found at {nimble_root}; initialize the submodule")

    model = Model(config)
    model.load(nimble_root)
    renderer = Renderer(model)

    stale = False
    for area in model.areas:
        stale |= write(area.path, render_area(area, model, renderer), args.check)
    stale |= write(
        os.path.join(NIMBLE_DIR, config["header"]), render_header(model), args.check
    )

    kinds = collections.Counter(
        entry.kconfig or "fixed in syscfg.h" for entry in model.defs.values()
    )
    print(", ".join(f"{count} {kind}" for kind, count in sorted(kinds.items())))

    if args.verbose:
        for note in model.notes:
            print(f"note: {note}", file=sys.stderr)
    for warning in model.warnings:
        print(f"warning: {warning}", file=sys.stderr)

    if args.check and stale:
        sys.exit("gen_syscfg: regenerate with third_party/nimble/scripts/gen_syscfg.py")


if __name__ == "__main__":
    main()
